 try{$month=trim($_POST['report_month']??'');$activities=trim($_POST['activities_done']??'');$suggestions=trim($_POST['suggestions']??'');if($activities==='')throw new Exception('فعالیت‌های انجام شده را وارد کنید.');$pdo->prepare('INSERT INTO teacher_reports(teacher_id,activities_done,suggestions,report_month) VALUES(?,?,?,?)')->execute([$teacherId,$activities,$suggestions,$month]);$msg='گزارش ماهوار ثبت شد.';}catch(Exception $e){$err=$e->getMessage();}
